DELETE FROM zentide_hub_member
WHERE hub_id=#{hubId} AND user_id=#{memberId}
  AND role<>'OWNER' AND membership_status='ACTIVE'

mapper.update:

UPDATE zentide_topic_link
SET counter_value=(
  SELECT calculated.counter_value
  FROM (
    SELECT COUNT(*) AS counter_value
    FROM zentide_topic_link pt
    JOIN zentide_interest_post p ON p.post_id=pt.post_id
    WHERE pt.topic_id=#{topicId}
      AND pt.post_id IS NOT NULL
      AND p.status='PUBLISHED'
  ) calculated
)
WHERE hub_id=#{hubId} AND topic_id=#{topicId}
